{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MEDMONGERS_DB.MAPLEMONK.MEDMONGERS_FLIPKART_ORDER_FULFILMENT_FACT_ITEMS AS WITH ranked_data AS ( SELECT order_date::TIMESTAMP_NTZ AS order_date, cast(NULLIF(REPLACE(order_approval_date, \'\"\', \'\'), \'\') as timestamp) AS order_approval_date, REPLACE(REPLACE(sku, \'\"\', \'\'), \'sku:\', \'\') AS sku, order_id AS reference_code, order_id, cast(NULLIF(order_cancellation_date, \'\') as timestamp) AS cancellation_date, REPLACE(cancellation_reason, \'_\', \' \') AS cancellation_reason, cast(NULLIF(order_ready_for_dispatch_on_date, \'\') as timestamp) AS order_ready_for_dispatch_on_date, cast(NULLIF(dispatch_after_date, \'\') as timestamp) AS manifest_date, cast(NULLIF(dispatch_by_date, \'\') as timestamp) AS dispatch_date, CASE WHEN deliver_by_date IN (\'N\', \'\') THEN NULL ELSE deliver_by_date::DATE END AS delivery_date, CASE WHEN UPPER(pickup_logistics_partner) LIKE \'%COD%\' THEN \'cod\' ELSE \'prepaid\' END AS payment_mode, cast(NULLIF(order_return_approval_date, \'\') as timestamp) AS return_approval_date, cast(NULLIF(order_service_completion_date, \'\') as timestamp) AS order_service_completion_date, return_id, REPLACE(return_reason, \'_\', \' \') AS return_reason, REPLACE(return_sub_reason, \'_\', \' \') AS return_sub_reason, REPLACE(order_item_id, \'OI:\', \'\') AS order_item_id, REPLACE(product_title, \'\"\', \'\') AS product_name, fulfilment_type, fulfilment_source, REPLACE(order_item_status, \'_\', \' \') AS order_item_status, REPLACE(delivery_tracking_id, \'DTr:\', \'\') AS fk_awb, REPLACE(REPLACE(pickup_logistics_partner, \'-cod\', \'\'), \'-prepaid\', \'\') AS courier, ROW_NUMBER() OVER (PARTITION BY order_id, order_item_id ORDER BY return_approval_date DESC) AS rn FROM medmongers_db.MAPLEMONK.FLIPKART_MEDMONGERS_ORDERS ) SELECT order_date, order_approval_date, sku, reference_code, order_id, cancellation_date, cancellation_reason, order_ready_for_dispatch_on_date, manifest_date, dispatch_date, delivery_date, payment_mode, return_approval_date, order_service_completion_date, return_id, return_reason, return_sub_reason, order_item_id, product_name, fulfilment_type, fulfilment_source, order_item_status, fk_awb, courier FROM ranked_data WHERE rn = 1; CREATE OR REPLACE TABLE medmongers_db.maplemonk.medmongers_Flipkart_sales_fact_items AS SELECT \'FLIPKART\' AS shop_name, s.\"Order ID\" order_id, s.\"Order ID\" AS order_name, NULL::VARCHAR AS customer_id, NULL::VARCHAR AS phone, \"HSN Code\" as HSN_Code, s.\"Order Type\" AS payment_type, NULL::VARCHAR AS tags, s.\"Order Item ID\" AS line_item_id, REPLACE(REPLACE(s.sku, \'\"\', \'\'), \'SKU:\', \'\')::VARCHAR AS SKU, REPLACE(s.FSN, \'\"\', \'\') AS product_id, CASE WHEN s.\"Event Sub Type\" = \'Return\' THEN 1 ELSE 0 END AS is_refund, null::VARCHAR AS city, UPPER(CASE WHEN s.\"Customer\'s Delivery State\" = \'-\' THEN (CASE WHEN s.\"Customer\'s Billing State\" = \'-\' THEN NULL ELSE s.\"Customer\'s Billing State\" END) ELSE s.\"Customer\'s Delivery State\" END) AS state, CASE WHEN s.\"Customer\'s Delivery Pincode\" = \'-\' THEN (CASE WHEN s.\"Customer\'s Billing Pincode\" = \'-\' THEN NULL ELSE s.\"Customer\'s Delivery Pincode\" END) ELSE s.\"Customer\'s Delivery Pincode\" END AS pincode, REPLACE(\"Product Title/Description\", \'\"\', \'\') AS PRODUCT_NAME, UPPER(sm.product_category) AS mapped_product_category, null::varchar as mapped_product_sub_category, UPPER(sm.product_name) AS mapped_product_name, sm.cost AS cogs, sm.commonsku AS commonsku, sm.mrp, sm.brand, CASE WHEN s.\"Order Date\" = \'-\' THEN NULL ELSE cast(s.\"Order Date\" as timestamp) END AS order_date, LEFT(s.\"Buyer Invoice Date\", 10)::DATE AS invoice_Date, f.delivery_date, f.cancellation_date, f.manifest_date, f.dispatch_date, f.return_approval_date, f.return_reason, f.return_sub_reason, f.order_service_completion_date, f.order_item_status, f.return_id, f.fulfilment_type, f.fulfilment_source, f.cancellation_reason, f.payment_mode, \"TDS Rate\"::FLOAT AS tds_rate, \"VAT Rate\"::FLOAT AS VAT_Rate, \"CGST Rate\"::FLOAT AS CGST_Rate, \"IGST Rate\"::FLOAT AS IGST_Rate, \"CST Amount\"::FLOAT AS CST_Amount, CASE WHEN \"TDS Amount\" <> \'NA\' THEN \"TDS Amount\"::FLOAT ELSE NULL END AS TDS_Amount, \"VAT Amount\"::FLOAT AS VAT_Amount, \"CGST Amount\"::FLOAT AS CGST_Amount, \"IGST Amount\"::FLOAT AS IGST_Amount, \"Type of tax\"::FLOAT AS Type_of_tax, CASE WHEN \"Usual Price\" <> \'NA\' AND \"Usual Price\" <> \'false\' THEN \"Usual Price\"::FLOAT ELSE NULL END AS Usual_Price, \"Seller GSTIN\" as Seller_GSTIN, ABS(COALESCE(\"Price after discount (Price before discount-Total discount)\"::FLOAT, 0)) AS line_item_sales, ABS(COALESCE(\"Shipping Charges\"::FLOAT, 0)) AS shipping_price, ABS(COALESCE(\"Item Quantity\"::FLOAT, 0)) AS quantity, ABS(COALESCE(\"Total TCS Deducted\"::FLOAT, 0)) AS tax, ABS( COALESCE(\"Price after discount (Price before discount-Total discount)\"::FLOAT, 0) / NULLIF((COALESCE(\"Price after discount (Price before discount-Total discount)\"::FLOAT, 0) + COALESCE(\"Total TCS Deducted\"::FLOAT, 0)), 0) ) AS overall_tax_rate, ABS(COALESCE(\"Total Discount\"::FLOAT, 0)) AS discount, ( ABS(COALESCE(\"Total Discount\"::FLOAT, 0)) / NULLIF((1 - (ABS(COALESCE(\"Total TCS Deducted\"::FLOAT, 0)) / NULLIF((ABS(COALESCE(\"Total TCS Deducted\"::FLOAT, 0)) + ABS(COALESCE(\"Price after discount (Price before discount-Total discount)\"::FLOAT, 0))), 0))), 0) ) AS discount_before_tax, ( ABS(COALESCE(\"Price after discount (Price before discount-Total discount)\"::FLOAT, 0)) - (ABS(COALESCE(\"Total Discount\"::FLOAT, 0)) / NULLIF((1 - (ABS(COALESCE(\"Total TCS Deducted\"::FLOAT, 0)) / NULLIF((ABS(COALESCE(\"Total TCS Deducted\"::FLOAT, 0)) + ABS(COALESCE(\"Price after discount (Price before discount-Total discount)\"::FLOAT, 0))), 0))), 0)) ) AS gross_sales_before_tax, ABS(COALESCE(\"Price after discount (Price before discount-Total discount)\"::FLOAT, 0)) AS total_sales, \'Flipkart Order\' AS Order_Channel, \"Beneficiary Name\" AS name, NULL::VARCHAR AS email, \"Order Shipped From (State)\" AS Order_Shipped_From_State, \"Warehouse ID\" as Warehouse_ID, \"Business Name\" Business_Name, f.courier, f.fk_awb FROM ( SELECT * FROM medmongers_db.maplemonk.flipkart_medmongers_sales WHERE LOWER(\"Event Sub Type\") LIKE \'%sale%\' ) s LEFT JOIN (select * from medmongers_db.maplemonk.MEDMONGERS_FLIPKART_ORDER_FULFILMENT_FACT_ITEMS qualify row_number() over (partition by order_id,order_item_id order by return_approval_date desc) =1 )f ON f.order_id = s.\"Order ID\" AND f.order_item_id = s.\"Order Item ID\" left join ( select channel_sku, upper(sku_code) as commonsku, upper(product_name) as product_name, upper(category) as product_category, cost, mrp, brand from medmongers_db.maplemonk.medmongers_final_sku_master where final_marketplace = \'FLIPKART\' qualify row_number() over (partition by lower(trim(channel_sku)) order by channelname) = 1 ) sm on lower(trim(sm.channel_sku)) = lower(trim(cast(replace(replace(s.sku,\'\"\',\'\'),\'SKU:\',\'\') as string))) ;",
                    "transaction": true
                }
            ) }}
